44		// ReasonContainerNotFound is a stale finding: the file no longer has the
45		// container it named, at the lines it named.
46		ReasonContainerNotFound = "The reported container is not at the reported lines of this file"
47		ReasonNotPlainBoolean   = "The value is not a plain true/false this fix can rewrite"
48		ReasonInlineMapping     = "This securityContext is written inline ({…}); the fix only edits block style"
49		ReasonNoInsertionPoint  = "No key of this container starts its own line, so there is nowhere to insert the setting"
50		ReasonNotPrivileged     = "The container is no longer privileged"
51		ReasonEscalationOff     = "The container already sets allowPrivilegeEscalation: false"
52		// ReasonPrivilegedContainer and ReasonSysAdmin are the API server's own
53		// validation: it refuses allowPrivilegeEscalation: false on a container
54		// that is privileged or adds CAP_SYS_ADMIN. The fix would pass Trivy's
55		// rule and produce a manifest nobody can apply.
56		ReasonPrivilegedContainer = "The container is privileged, and the API server refuses allowPrivilegeEscalation: false with it — fix KSV-0017 first"
57		ReasonSysAdmin            = "The container adds CAP_SYS_ADMIN, and the API server refuses allowPrivilegeEscalation: false with it"
