94	// fixPrivileged satisfies KSV-0017 by turning privileged: true into false.
95	// The key exists — that is what the rule fired on — so this is a token swap.
96	func fixPrivileged(content []byte, f scan.Finding) ([]patch.Edit, string) {
97		c, reason := reportedContainer(content, f)
98		if reason != "" {
99			return nil, reason
100		}
101		_, sc, _ := k8s.Entry(c, "securityContext")
102		var value *yaml.Node
103		if sc != nil {
104			_, value, _ = k8s.Entry(sc, "privileged")
105		}
106		if value == nil || value.Value == "false" {
107			return nil, ReasonNotPrivileged
108		}
109		return swapBoolean(content, value)
110	}
111	
112	// fixPrivilegeEscalation satisfies KSV-0001: allowPrivilegeEscalation: false on
113	// the container Trivy named. The rule fires on a value of true and on no value
114	// at all, so this is either a swap or an insertion, and an insertion goes
115	// above an existing key, at that key's indentation.
116	func fixPrivilegeEscalation(content []byte, f scan.Finding) ([]patch.Edit, string) {
117		c, reason := reportedContainer(content, f)
118		if reason != "" {
119			return nil, reason
120		}
121		_, sc, hasContext := k8s.Entry(c, "securityContext")
122		if hasContext {
123			if reason := escalationRefused(sc); reason != "" {
124				return nil, reason
125			}
126			if _, value, ok := k8s.Entry(sc, "allowPrivilegeEscalation"); ok {
127				if value.Value == "false" {
128					return nil, ReasonEscalationOff
129				}
130				return swapBoolean(content, value)
131			}
132			if sc.Kind != yaml.MappingNode || sc.Style&yaml.FlowStyle != 0 || len(sc.Content) == 0 {
133				return nil, ReasonInlineMapping
134			}
135			return insertAbove(content, sc.Content[0], "allowPrivilegeEscalation: false")
136		}
137		for i := 0; i < len(c.Content); i += 2 {
138			if _, _, ok := k8s.OwnLineIndent(content, c.Content[i]); ok {
139				nl := k8s.LineEnding(content)
140				return insertAbove(content, c.Content[i], "securityContext:"+nl+"{indent}  allowPrivilegeEscalation: false")
141			}
142		}
143		return nil, ReasonNoInsertionPoint
144	}
