146	// escalationRefused is the API server's validation of a securityContext that
147	// would carry allowPrivilegeEscalation: false.
148	func escalationRefused(sc *yaml.Node) string {
149		if k8s.Scalar(sc, "privileged") == "true" {
150			return ReasonPrivilegedContainer
151		}
152		if _, caps, ok := k8s.Entry(sc, "capabilities"); ok {
153			if _, add, ok := k8s.Entry(caps, "add"); ok {
154				for _, c := range add.Content {
155					if name := strings.TrimPrefix(strings.ToUpper(c.Value), "CAP_"); name == "SYS_ADMIN" {
156						return ReasonSysAdmin
157					}
158				}
159			}
160		}
161		return ""
162	}
