164	// fixRemovedAPI satisfies K8S-API-REMOVED by renaming the apiVersion, for the
165	// kinds where that is the entire migration.
166	func fixRemovedAPI(content []byte, f scan.Finding) ([]patch.Edit, string) {
167		if reason := plainManifest(f); reason != "" {
168			return nil, reason
169		}
170		doc, ok := k8s.DocumentAt(content, f.Line)
171		if !ok {
172			return nil, ReasonUnreadableSpan
173		}
174		_, version, ok := k8s.Entry(doc, "apiVersion")
175		if !ok {
176			return nil, ReasonUnreadableSpan
177		}
178		target, ok := renamedAPIs[version.Value+" "+k8s.Scalar(doc, "kind")]
179		if !ok {
180			return nil, ReasonNoSimpleMigration
181		}
182		start, end, ok := k8s.PlainScalarSpan(content, version)
183		if !ok {
184			return nil, ReasonUnreadableSpan
185		}
186		return []patch.Edit{{Span: patch.Span{Start: start, End: end}, Old: version.Value, New: target}}, ""
187	}
