189	// reportedContainer finds the container a KSV finding is about: in the
190	// document holding the reported line, by the name Trivy's message gives. A
191	// finding whose file no longer matches is declined rather than applied to
192	// whatever sits there now.
193	func reportedContainer(content []byte, f scan.Finding) (*yaml.Node, string) {
194		if reason := plainManifest(f); reason != "" {
195			return nil, reason
196		}
197		m := containerInMessage.FindStringSubmatch(f.Message)
198		if m == nil || f.Line <= 0 {
199			return nil, ReasonUnreadableSpan
200		}
201		doc, ok := k8s.DocumentAt(content, f.Line)
202		if !ok {
203			return nil, ReasonUnreadableSpan
204		}
205		for _, c := range k8s.Containers(doc) {
206			if k8s.Scalar(c, "name") != m[1] {
207				continue
208			}
209			if f.EndLine > 0 && (c.Line < f.Line || c.Line > f.EndLine) {
210				continue
211			}
212			return c, ""
213		}
214		return nil, ReasonContainerNotFound
215	}
