217	// swapBoolean replaces a plain true with false.
218	func swapBoolean(content []byte, value *yaml.Node) ([]patch.Edit, string) {
219		if value.Value != "true" {
220			return nil, ReasonNotPlainBoolean
221		}
222		start, end, ok := k8s.PlainScalarSpan(content, value)
223		if !ok {
224			return nil, ReasonNotPlainBoolean
225		}
226		return []patch.Edit{{Span: patch.Span{Start: start, End: end}, Old: value.Value, New: "false"}}, ""
227	}
