229	// insertAbove adds text as new lines above key, at key's indentation. A
230	// "{indent}" in text stands for that indentation on the lines after the first.
231	func insertAbove(content []byte, key *yaml.Node, text string) ([]patch.Edit, string) {
232		lineStart, indent, ok := k8s.OwnLineIndent(content, key)
233		if !ok {
234			return nil, ReasonNoInsertionPoint
235		}
236		text = strings.ReplaceAll(text, "{indent}", indent)
237		return []patch.Edit{{
238			Span: patch.Span{Start: lineStart, End: lineStart},
239			New:  indent + text + k8s.LineEnding(content),
240		}}, ""
241	}
